-- ---------------------------------------------------------------------
-- SECTION 1b — FUNCTION EXECUTE PRIVILEGES (final, non-contradictory)
-- ---------------------------------------------------------------------
-- Trigger-only functions: nobody calls them directly.
REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.update_updated_at_column() FROM PUBLIC, anon, authenticated;

-- has_role(): only referenced by policies that are restricted to the
-- `authenticated` role, so anon never needs it.
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;

-- is_staff(): referenced by policies that apply TO anon as well
-- (public reads of vehicles / blog_posts / collections evaluate
-- `... OR public.is_staff(auth.uid())`), so anon genuinely requires it.
REVOKE ALL ON FUNCTION public.is_staff(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_staff(uuid) TO anon, authenticated;

-- profiles extras used by the legacy link
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS avatar_url TEXT;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS legacy_user_id INTEGER;
CREATE UNIQUE INDEX IF NOT EXISTS profiles_legacy_user_id_key ON public.profiles (legacy_user_id) WHERE legacy_user_id IS NOT NULL;

-- ---------------------------------------------------------------------
-- SECTION 2 — STORAGE
-- Private bucket that holds the vehicle photos. Create the bucket in the
-- dashboard (Storage -> New bucket -> name `vehicle-photos`, NOT public),
-- or leave the insert below which does the same thing.
-- ---------------------------------------------------------------------
INSERT INTO storage.buckets (id, name, public)
VALUES ('vehicle-photos', 'vehicle-photos', false)
ON CONFLICT (id) DO NOTHING;

-- The site serves photos through the server-side proxy route
-- /api/public/vehicle-photos/*, which reads the object with the anon key,
-- so a read policy for anon on this bucket is required.
DROP POLICY IF EXISTS "public reads vehicle photo files" ON storage.objects;
CREATE POLICY "public reads vehicle photo files"
  ON storage.objects FOR SELECT TO anon, authenticated
  USING (bucket_id = 'vehicle-photos');

-- Staff may upload/replace/remove photo objects.
DROP POLICY IF EXISTS "staff manage vehicle photo objects" ON storage.objects;
CREATE POLICY "staff manage vehicle photo objects"
  ON storage.objects FOR ALL TO authenticated
  USING (bucket_id = 'vehicle-photos' AND public.is_staff(auth.uid()))
  WITH CHECK (bucket_id = 'vehicle-photos' AND public.is_staff(auth.uid()));

