ON CONFLICT DO NOTHING;

-- ---------------------------------------------------------------------
-- SECTION 4 — LEGACY CONTENT IMPORT (mycarco_db -> public)
-- Read-only against mycarco_db. Nothing there is created, altered,
-- deleted or dropped. mc_users.password is never copied anywhere.
-- ---------------------------------------------------------------------

-- 4a. Blog posts: all rows of mycarco_db.mc_blog -> public.blog_posts
INSERT INTO public.blog_posts
  (slug, title, excerpt, body, cover_image_url, author_name, published, published_at, created_at, updated_at)
SELECT
  b.slug,
  b.title,
  b.excerpt,
  coalesce(b.body, ''),
  b.image_url,
  b.author_name,
  (lower(coalesce(b.status,'')) = 'published'),
  b.published_at,
  coalesce(b.created_at, now()),
  coalesce(b.updated_at, now())
FROM mycarco_db.mc_blog b
ON CONFLICT (slug) DO NOTHING;

-- 4b. mc_cars — intentionally NOT imported again. All 38 vehicles are
--     already inserted in Section 3 in normalised form (VIN, slug,
--     price_cents, enums) together with their 190 photo rows.

-- 4c. mc_contacts / mc_financing / mc_saved_cars — verified empty at
--     export time (0 rows each), so there is nothing to migrate.

-- 4d. mc_settings — feed-sync bookkeeping keys only; the website's
--     settings row is inserted in Section 3.

-- ---------------------------------------------------------------------
-- SECTION 4e — BACKFILL FOR AUTH USERS THAT ALREADY EXIST
-- handle_new_user() only fires on INSERT into auth.users, so accounts
-- created before this file runs have no profile. This creates them.
-- Matching is auth.users.email = mycarco_db.mc_users.email, case-
-- insensitive. No auth.users row is created, changed or deleted here.
-- ---------------------------------------------------------------------

-- Profiles for every existing Auth user that matches a legacy user.
INSERT INTO public.profiles (id, full_name, email, phone, avatar_url, legacy_user_id)
SELECT DISTINCT ON (au.id)
       au.id,
       nullif(btrim(u.name), ''),
       lower(btrim(u.email)),
       nullif(btrim(u.phone), ''),
       nullif(btrim(u.avatar), ''),
       u.id
FROM auth.users au
JOIN mycarco_db.mc_users u
  ON lower(btrim(u.email)) = lower(btrim(au.email))
ORDER BY au.id, u.id
ON CONFLICT (id) DO UPDATE SET
  full_name      = coalesce(profiles.full_name, EXCLUDED.full_name),
  email          = coalesce(EXCLUDED.email, profiles.email),
  phone          = coalesce(profiles.phone, EXCLUDED.phone),
  avatar_url     = coalesce(profiles.avatar_url, EXCLUDED.avatar_url),
  legacy_user_id = coalesce(profiles.legacy_user_id, EXCLUDED.legacy_user_id);

-- Profiles for any other existing Auth user (no legacy match), so the
-- app never sees a signed-in user without a profile row.
INSERT INTO public.profiles (id, email)
SELECT au.id, lower(btrim(au.email))
FROM auth.users au
ON CONFLICT (id) DO NOTHING;

-- Roles, derived ONLY from the trusted legacy record.
-- admin/owner/superadmin -> owner; editor/staff/manager -> editor;
-- anything else -> shopper.
INSERT INTO public.user_roles (user_id, role)
SELECT p.id,
       CASE lower(btrim(coalesce(u.role, '')))
         WHEN 'admin'      THEN 'owner'::public.app_role
         WHEN 'owner'      THEN 'owner'::public.app_role
         WHEN 'superadmin' THEN 'owner'::public.app_role
         WHEN 'editor'     THEN 'editor'::public.app_role
         WHEN 'staff'      THEN 'editor'::public.app_role
         WHEN 'manager'    THEN 'editor'::public.app_role
         ELSE 'shopper'::public.app_role
       END
FROM public.profiles p
JOIN mycarco_db.mc_users u ON u.id = p.legacy_user_id
ON CONFLICT (user_id, role) DO NOTHING;

-- Default shopper role for existing Auth users with no legacy match.
INSERT INTO public.user_roles (user_id, role)
SELECT p.id, 'shopper'::public.app_role
FROM public.profiles p
WHERE p.legacy_user_id IS NULL
  AND NOT EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = p.id)
ON CONFLICT (user_id, role) DO NOTHING;

COMMIT;

